ENTRIES.push(...[["SPCC: bảng thành phần và chú thích không mặc định bảo đảm thử kéo; không đồng nhất với SPCCT.", "SPCC chemistry and notes on tensile guarantees; SPCC is distinct from SPCCT."], ["SPHC: bảng hóa học và cơ tính theo chiều dày; bảng hãng viện dẫn bản JIS 2018.", "SPHC chemistry and thickness-based properties; the catalogue cites the 2018 JIS edition."], ["Tham khảo phạm vi tấm SPHC 1,2–14 mm; không dùng bảng SPCC trong nguồn này làm bảo đảm thử kéo.", "SPHC sheet range reference: 1.2–14 mm; this source is not used to guarantee SPCC tensile properties."], ["Thép tấm tạo hình", "Sheet steels for forming"], ["SPCC và SPHC là hai mác khác nhau về quá trình cán và tiêu chuẩn; không tự thay thế chỉ dựa vào tên hoặc chiều dày.", "SPCC and SPHC differ in rolling process and standard; do not substitute on designation or thickness alone."], ["SPCC thường không quy định Re/Rm/A; không mặc định gán Rm ≥ 270 MPa. Khi có thỏa thuận bảo đảm thử kéo và độ giãn dài, định danh là SPCCT.", "SPCC normally has no specified Re/Rm/A; do not assume Rm ≥ 270 MPa. Agreed tensile and elongation guarantees use the designation SPCCT."], ["Thành phần theo Nippon Steel U003en (2020): Mn tối đa 1,00%; kiểm tra lại phiên bản tiêu chuẩn và chứng chỉ của đơn hàng.", "Chemistry follows Nippon Steel U003en (2020): Mn maximum 1.00%; verify the contract standard edition and certificate."], ["Điều chất tiêu chuẩn (S); hoàn thiện bề mặt theo đơn hàng", "Standard temper (S); surface finish per order"], ["Vỏ tủ, tủ điện và chi tiết chấn gấp", "Cabinets, electrical enclosures and bent parts"], ["Vỏ thiết bị gia dụng và chi tiết tạo hình đơn giản", "Appliance panels and simple formed parts"], ["SPCC là loại thông dụng; yêu cầu dập vuốt cao hơn cần xem các cấp chuyên dụng và điều kiện đơn hàng.", "SPCC is commercial quality; more demanding drawing requires suitable drawing grades and order conditions."], ["Thép tấm cán nguội SPCC", "SPCC cold-rolled sheet steel"], ["Thép tấm và cuộn cán nguội", "Cold-rolled sheets and coils"], ["Thép carbon thấp cán nguội loại thông dụng, dùng cho chấn gấp và tạo hình đơn giản.", "Commercial-quality cold-rolled low-carbon steel for bending and simple forming."], ["Bảng chỉ nêu Rm và A, không nêu giới hạn chảy hoặc KV. Mẫu kéo JIS No.5 dọc hướng cán; chỉ tra cứu trong 1,2–14 mm.", "The table specifies Rm and A, not yield strength or KV. JIS No.5 longitudinal tensile specimen; lookup is limited to 1.2–14 mm."], ["Rm tối đa 440 MPa chỉ áp dụng khi người mua và nhà cung cấp thỏa thuận; bản ghi không đặt giới hạn tối đa mặc định.", "The 440 MPa Rm maximum requires purchaser–supplier agreement; no default maximum is assigned here."], ["Bảng JFE viện dẫn JIS G 3131:2018; cần đối chiếu phiên bản áp dụng của đơn hàng.", "The JFE table cites JIS G 3131:2018; check the edition applicable to the order."], ["Chi tiết thép tấm chấn, dập và tạo hình thông dụng", "Sheet parts for general bending, stamping and forming"], ["Thép tấm cán nóng SPHC", "SPHC hot-rolled sheet steel"], ["Thép tấm và cuộn cán nóng", "Hot-rolled sheets and coils"], ["Cán nóng; bề mặt đen hoặc tẩy gỉ theo đơn hàng", "Hot-rolled; black or pickled surface per order"], ["Thép mềm cán nóng loại thông dụng cho gia công tạo hình; cơ tính tra theo chiều dày, không phải cấp thép kết cấu có giới hạn chảy quy định.", "Commercial-quality hot-rolled mild steel for forming; properties depend on thickness, with no specified structural yield grade."], ["Chiều dày danh nghĩa của tấm hoặc dải SPHC.", "Nominal SPHC sheet or strip thickness."], ["Sử dụng cho tạo hình thông dụng theo yêu cầu chi tiết.", "Use for general forming according to component requirements."], ["Không quy định cơ tính theo mác", "Mechanical properties not specified by grade"], ["Giới hạn chảy Re", "Yield strength Re"]]);
// SGCC / ZAM — distinguish coating and steel substrate.
ENTRIES.push(...[["SGCC: thành phần thép nền; trị số kéo trong ngoặc là tham khảo, cần thỏa thuận khi bảo đảm.", "SGCC substrate chemistry; parenthesized tensile values are references and require agreement for guarantees."], ["Thành phần điển hình của lớp mạ ZAM và thông tin các loại thép nền.", "Typical ZAM coating composition and information on substrate grades."], ["Cơ tính phải theo cấp nền cụ thể, như SGMCC, SGMHC hoặc cấp cường độ SGMC/SGMH.", "Properties depend on the specific grade, such as SGMCC, SGMHC or SGMC/SGMH strength grades."], ["Thép tấm mạ", "Metallic-coated sheet steels"], ["Ký hiệu và khối lượng lớp mạ theo đơn hàng/chứng chỉ; chưa chọn giá trị mặc định.", "Coating designation and mass follow the order/certificate; no default is selected."], ["Thành phần dưới đây thuộc lớp mạ, không phải thành phần hợp kim của thép nền. Khối lượng mạ cần phân biệt tổng hai mặt và mỗi mặt.", "The composition below belongs to the coating, not the steel substrate. Distinguish total two-sided coating mass from mass per side."], ["SGCC và ZAM không tự tương đương: cần đối chiếu cấp thép nền, lớp mạ, khối lượng mạ và điều kiện sử dụng.", "SGCC and ZAM are not automatic equivalents: compare substrate grade, coating type, coating mass and service conditions."], ["CSC nêu 205 MPa và 270 MPa trong ngoặc cho SGCC: chỉ tham khảo, không phải cơ tính bảo đảm mặc định; A và KV chưa có trong bản ghi.", "CSC lists 205 MPa and 270 MPa in parentheses for SGCC: reference values, not default guaranteed properties; A and KV are not provided here."], ["Mạ kẽm nhúng nóng (Zn)", "Hot-dip zinc coating (Zn)"], ["Chi tiết thép tấm gia công tạo hình thông dụng", "General formed sheet-metal components"], ["Thép tấm mạ kẽm nhúng nóng SGCC", "SGCC hot-dip galvanized sheet steel"], ["Dữ liệu theo catalogue CSC 2025 viện dẫn JIS G 3302:2022; kiểm tra phiên bản và điều kiện đơn hàng.", "Data follows the 2025 CSC catalogue citing JIS G 3302:2022; verify the contract edition and conditions."], ["Thép tấm và cuộn mạ kẽm, nền cán nguội", "Zinc-coated sheets and coils, cold-rolled substrate"], ["Mạ nhúng nóng; hoàn thiện bề mặt theo đơn hàng", "Hot-dip coated; surface finish per order"], ["Thép tấm mạ kẽm nhúng nóng loại thông dụng; cấp SGCC và chỉ định lớp mạ cần được xác định riêng.", "Commercial-quality hot-dip galvanized sheet; SGCC grade and coating designation must be specified separately."], ["Giới hạn thành phần của thép nền SGCC; không phải thành phần lớp mạ kẽm.", "Chemical limits for the SGCC steel substrate, not the zinc coating."], ["Thành phần chính", "Principal constituent"], ["ZAM là thương hiệu sản phẩm mạ Zn–Al–Mg của Nippon Steel, không phải một mác thép có cơ tính duy nhất. Chưa chọn cấp nền nên không gán Re/Rm/A/KV chung.", "ZAM is a Nippon Steel Zn–Al–Mg coated-product brand, not one steel grade with unique properties. No substrate grade is selected, so no common Re/Rm/A/KV is assigned."], ["Chưa chọn cấp thép nền; không đưa 6% Al và 3% Mg của lớp mạ vào bảng thành phần thép nền.", "No substrate grade is selected; the coating values of 6% Al and 3% Mg are not entered as substrate chemistry."], ["Chi tiết cho nhà lắp ghép và vật tư nông nghiệp", "Components for prefabricated housing and agricultural equipment"], ["Phụ kiện điện và các cấu kiện thép tạo hình theo thiết kế", "Electrical fittings and formed steel members according to design"], ["Thép tấm mạ hợp kim Zn–Al–Mg ZAM", "ZAM Zn–Al–Mg alloy-coated sheet steel"], ["JIS G 3323 được Nippon Steel viện dẫn cho các cấp sản phẩm; xác nhận cấp đầy đủ và chứng chỉ khi đặt hàng.", "Nippon Steel cites JIS G 3323 for product grades; confirm the complete designation and certificate when ordering."], ["Thép tấm và cuộn mạ hợp kim Zn–Al–Mg", "Zn–Al–Mg alloy-coated sheets and coils"], ["Mạ nhúng nóng; cấp nền và xử lý bề mặt chưa chọn", "Hot-dip coated; substrate grade and surface treatment not selected"], ["Dòng sản phẩm thép mạ hợp kim Zn–Al–Mg; thành phần mạ điển hình gồm Zn, khoảng 6% Al và 3% Mg. Cơ tính theo cấp nền cụ thể.", "Zn–Al–Mg alloy-coated steel product family; typical coating contains Zn, about 6% Al and 3% Mg. Mechanical properties depend on the specific substrate grade."], ["Mạ hợp kim Zn–Al–Mg (ZAM)", "Zn–Al–Mg alloy coating (ZAM)"], ["Nền hợp kim lớp mạ", "Coating alloy base"], ["Loại lớp mạ", "Coating type"], ["Cấp thép nền", "Substrate grade"], ["Chưa chọn cấp thép nền", "Substrate grade not selected"], ["Ký hiệu lớp mạ", "Coating designation"], ["Khối lượng mạ tổng hai mặt", "Total two-sided coating mass"], ["Theo đơn hàng / chứng chỉ", "Per order / certificate"], ["Lớp mạ và thông tin đặt hàng", "Coating and ordering information"], ["Thông tin lớp mạ", "Coating information"], ["Thành phần lớp mạ", "Coating composition"], ["Thông số", "Parameter"], ["Giá trị / vai trò", "Value / role"], ["Thành phần thép nền", "Steel substrate composition"], ["Lớp mạ", "Coating"]]);
// CB240-T — Vietnamese plain reinforcing bar, A5 distinct from Agt.
ENTRIES.push(...[["Bản tiêu chuẩn công bố trên website Hòa Phát; xem Bảng 2, 3, 5, 6 và Điều 8.", "Standard copy hosted by Hoa Phat; see Tables 2, 3, 5, 6 and Clause 8."], ["Bảng hãng cho thép cuộn d6/d8: giới hạn chảy 240 MPa, bền kéo 380 MPa, giãn dài 20%.", "Manufacturer table for d6/d8 coils: 240 MPa yield, 380 MPa tensile strength, 20% elongation."], ["CB là cốt bê tông; 240 chỉ giới hạn chảy trên quy định 240 MPa; T là thanh tròn trơn.", "CB denotes concrete reinforcement; 240 specifies 240 MPa upper yield strength; T denotes plain round bars."], ["A₅ ≥ 20% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 2% là giãn dài tổng tại lực lớn nhất. Không coi hai chỉ tiêu là cùng một phép đo.", "A₅ ≥ 20% is elongation after fracture with L₀ = 5d; Agt ≥ 2% is total elongation at maximum force. These are different measurements."], ["Thử uốn 160–180°, gối uốn đường kính 2d khi d ≤ 40 mm; sau thử không có gãy hoặc nứt ngang nhìn thấy được. Trường hợp khác cần thỏa thuận theo tiêu chuẩn.", "Bend test: 160–180°, mandrel diameter 2d for d ≤ 40 mm; no visible rupture or transverse cracks. Other cases require agreement under the standard."], ["Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 240 MPa làm ứng suất thiết kế mặc định.", "Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 240 MPa as a default design stress."], ["d là đường kính danh nghĩa của thanh tròn trơn. Bảng 2 nêu các cỡ 6–40 mm; cỡ khác cần thỏa thuận giữa nhà sản xuất và người mua.", "d is nominal plain-bar diameter. Table 2 lists sizes from 6 to 40 mm; other sizes require manufacturer–purchaser agreement."], ["P và S là giới hạn phân tích mẻ nấu. Không tự đặt hàm lượng C, Si, Mn hoặc CEV khi bảng không quy định cho CB240-T.", "P and S are cast-analysis limits. Do not assign C, Si, Mn or CEV limits that the table does not specify for CB240-T."], ["Áp dụng cho thép tròn trơn làm cốt bê tông dạng thanh thẳng, cuộn hoặc nắn thẳng; không phải thép thanh vằn CB…-V.", "Applies to plain concrete-reinforcement bars supplied straight, coiled or straightened; distinct from CB…-V ribbed bars."], ["Thép thanh tròn trơn làm cốt bê tông theo bản vẽ thiết kế", "Plain concrete-reinforcement bars according to the design drawings"], ["Thép cốt bê tông tròn trơn CB240-T", "CB240-T plain concrete-reinforcing steel"], ["Tham chiếu TCVN 1651-1:2018, Bảng 2, 3, 5, 6 và Điều 8; kiểm tra chứng chỉ của lô hàng.", "Reference: TCVN 1651-1:2018, Tables 2, 3, 5, 6 and Clause 8; check the batch certificate."], ["Thép thanh tròn trơn; dạng thanh hoặc cuộn", "Plain round reinforcing bars; straight lengths or coils"], ["Trạng thái cung cấp theo nhà sản xuất và đơn hàng", "Delivery condition according to manufacturer and order"], ["Mác thép cốt bê tông theo tiêu chuẩn Việt Nam, giới hạn chảy trên tối thiểu 240 MPa; ký hiệu đầy đủ là CB240-T.", "Vietnamese-standard concrete-reinforcing steel with minimum upper yield strength of 240 MPa; the full designation is CB240-T."], ["A₅ ≥ 20% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 2% là giãn dài tổng tại lực lớn nhất. Không coi hai chỉ tiêu là cùng một phép đo. Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 240 MPa làm ứng suất thiết kế mặc định.", "A₅ ≥ 20% is elongation after fracture with L₀ = 5d; Agt ≥ 2% is total elongation at maximum force. These are different measurements. Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 240 MPa as a default design stress."], ["Thép cốt bê tông", "Concrete-reinforcing steels"], ["Giới hạn chảy ReH", "Upper yield strength ReH"], ["Độ giãn dài A5", "Elongation after fracture A5"]]);
// TCVN 1651-2:2018 — ribbed reinforcing bars.
ENTRIES.push(...[["Bản tiêu chuẩn lưu tại VNCE; xem Bảng 2, 4, 6, 7, 8 và Điều 8.", "Standard copy hosted by VNCE; see Tables 2, 4, 6, 7, 8 and Clause 8."], ["Bảng cơ tính thép thanh vằn và đường kính gối uốn theo cỡ thanh.", "Mechanical properties of ribbed bars, with bend-mandrel diameters by bar size."], ["d là đường kính danh nghĩa của thanh vằn. Bảng 2 liệt kê 6, 8, 10, 12, 14, 16, 18, 20, 22, 25, 28, 32, 36, 40 và 50 mm; cỡ khác cần thỏa thuận.", "d is nominal ribbed-bar diameter. Table 2 lists 6, 8, 10, 12, 14, 16, 18, 20, 22, 25, 28, 32, 36, 40 and 50 mm; other sizes require agreement."], ["Thép thanh vằn làm cốt bê tông, cung cấp dạng thẳng, cuộn hoặc nắn thẳng; lựa chọn theo bản vẽ và chứng chỉ lô hàng.", "Ribbed concrete-reinforcement bars supplied straight, coiled or straightened; select according to design drawings and the batch certificate."], ["Trạng thái thử kéo theo Bảng 7 phụ thuộc công nghệ và dạng cung cấp. Hóa già để chuẩn bị mẫu thử không phải chỉ dẫn nhiệt luyện sản phẩm.", "Tensile-test condition under Table 7 depends on manufacturing route and delivery form. Test-specimen ageing is not a product heat-treatment instruction."], ["Khả năng hàn cần đánh giá theo thành phần thực tế của lô, CEV và quy trình hàn được phê duyệt; tên mác không tự xác nhận điều kiện hàn.", "Assess weldability using actual batch chemistry, CEV and an approved welding procedure; the grade name alone does not establish welding conditions."], ["Thép thanh vằn làm cốt bê tông theo bản vẽ thiết kế", "Ribbed concrete-reinforcement bars according to design drawings"], ["A₅ ≥ 16% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 8% là giãn dài tổng tại lực lớn nhất. Chọn A hoặc Agt theo thỏa thuận; nếu không quy định riêng, nên chọn Agt. Không coi cả hai là yêu cầu đồng thời mặc định.", "A₅ ≥ 16% is elongation after fracture with L₀ = 5d; Agt ≥ 8% is total elongation at maximum force. Select A or Agt by agreement; absent a specific requirement, Agt is preferred. Do not assume both are mandatory simultaneously."], ["Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 300 MPa làm ứng suất thiết kế mặc định.", "Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 300 MPa as a default design stress."], ["Khi yêu cầu thử uốn: góc 160–180°, đường kính gối uốn 3d khi d ≤ 16 mm, 6d khi 16 < d ≤ 32 mm, 7d khi 32 < d ≤ 50 mm; không có gãy hoặc nứt ngang nhìn thấy được.", "When a bend test is required: angle 160–180°, mandrel diameter 3d for d ≤ 16 mm, 6d for 16 < d ≤ 32 mm, and 7d for 32 < d ≤ 50 mm; no visible rupture or transverse cracks."], ["Giới hạn phân tích mẻ nấu theo Bảng 4; dung sai phân tích sản phẩm theo Bảng 5. CB300-V không có giới hạn C, Si, Mn hoặc CEV trong Bảng 4.", "Cast-analysis limits under Table 4; product-analysis tolerances under Table 5. Table 4 specifies no C, Si, Mn or CEV limit for CB300-V."], ["CB là cốt bê tông; 300 chỉ giới hạn chảy trên quy định 300 MPa; V là thanh vằn.", "CB denotes concrete reinforcement; 300 specifies 300 MPa upper yield strength; V denotes ribbed bars."], ["A₅ ≥ 16% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 8% là giãn dài tổng tại lực lớn nhất. Chọn A hoặc Agt theo thỏa thuận; nếu không quy định riêng, nên chọn Agt. Không coi cả hai là yêu cầu đồng thời mặc định. Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 300 MPa làm ứng suất thiết kế mặc định.", "A₅ ≥ 16% is elongation after fracture with L₀ = 5d; Agt ≥ 8% is total elongation at maximum force. Select A or Agt by agreement; absent a specific requirement, Agt is preferred. Do not assume both are mandatory simultaneously. Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 300 MPa as a default design stress."], ["Thép cốt bê tông thanh vằn CB300-V", "CB300-V ribbed concrete-reinforcing steel"], ["Tham chiếu TCVN 1651-2:2018, Bảng 2, 4, 5, 6, 7, 8 và Điều 8; kiểm tra chứng chỉ của lô hàng.", "Reference: TCVN 1651-2:2018, Tables 2, 4, 5, 6, 7, 8 and Clause 8; check the batch certificate."], ["Thép thanh vằn; dạng thanh, cuộn hoặc nắn thẳng", "Ribbed reinforcing bars; straight lengths, coils or straightened products"], ["Trạng thái cung cấp theo nhà sản xuất và đơn hàng", "Delivery condition according to manufacturer and order"], ["Mác thép thanh vằn cốt bê tông theo tiêu chuẩn Việt Nam, giới hạn chảy trên tối thiểu 300 MPa; ký hiệu đầy đủ là CB300-V.", "Vietnamese-standard ribbed concrete-reinforcing steel with minimum upper yield strength of 300 MPa; the full designation is CB300-V."], ["A₅ ≥ 14% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 8% là giãn dài tổng tại lực lớn nhất. Chọn A hoặc Agt theo thỏa thuận; nếu không quy định riêng, nên chọn Agt. Không coi cả hai là yêu cầu đồng thời mặc định.", "A₅ ≥ 14% is elongation after fracture with L₀ = 5d; Agt ≥ 8% is total elongation at maximum force. Select A or Agt by agreement; absent a specific requirement, Agt is preferred. Do not assume both are mandatory simultaneously."], ["Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 400 MPa làm ứng suất thiết kế mặc định.", "Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 400 MPa as a default design stress."], ["Khi yêu cầu thử uốn: góc 160–180°, đường kính gối uốn 4d khi d ≤ 16 mm, 6d khi 16 < d ≤ 32 mm, 7d khi 32 < d ≤ 50 mm; không có gãy hoặc nứt ngang nhìn thấy được.", "When a bend test is required: angle 160–180°, mandrel diameter 4d for d ≤ 16 mm, 6d for 16 < d ≤ 32 mm, and 7d for 32 < d ≤ 50 mm; no visible rupture or transverse cracks."], ["Giới hạn phân tích mẻ nấu theo Bảng 4; dung sai phân tích sản phẩm theo Bảng 5. CEV ≤ 0,56% theo công thức của tiêu chuẩn; giá trị hoặc công thức khác cần thỏa thuận.", "Cast-analysis limits under Table 4; product-analysis tolerances under Table 5. CEV ≤ 0.56% using the standard formula; other values or formulae require agreement."], ["CB là cốt bê tông; 400 chỉ giới hạn chảy trên quy định 400 MPa; V là thanh vằn.", "CB denotes concrete reinforcement; 400 specifies 400 MPa upper yield strength; V denotes ribbed bars."], ["A₅ ≥ 14% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 8% là giãn dài tổng tại lực lớn nhất. Chọn A hoặc Agt theo thỏa thuận; nếu không quy định riêng, nên chọn Agt. Không coi cả hai là yêu cầu đồng thời mặc định. Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 400 MPa làm ứng suất thiết kế mặc định.", "A₅ ≥ 14% is elongation after fracture with L₀ = 5d; Agt ≥ 8% is total elongation at maximum force. Select A or Agt by agreement; absent a specific requirement, Agt is preferred. Do not assume both are mandatory simultaneously. Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 400 MPa as a default design stress."], ["Thép cốt bê tông thanh vằn CB400-V", "CB400-V ribbed concrete-reinforcing steel"], ["Mác thép thanh vằn cốt bê tông theo tiêu chuẩn Việt Nam, giới hạn chảy trên tối thiểu 400 MPa; ký hiệu đầy đủ là CB400-V.", "Vietnamese-standard ribbed concrete-reinforcing steel with minimum upper yield strength of 400 MPa; the full designation is CB400-V."], ["Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 500 MPa làm ứng suất thiết kế mặc định.", "Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 500 MPa as a default design stress."], ["Khi yêu cầu thử uốn: góc 160–180°, đường kính gối uốn 5d khi d ≤ 16 mm, 6d khi 16 < d ≤ 32 mm, 7d khi 32 < d ≤ 50 mm; không có gãy hoặc nứt ngang nhìn thấy được.", "When a bend test is required: angle 160–180°, mandrel diameter 5d for d ≤ 16 mm, 6d for 16 < d ≤ 32 mm, and 7d for 32 < d ≤ 50 mm; no visible rupture or transverse cracks."], ["Giới hạn phân tích mẻ nấu theo Bảng 4; dung sai phân tích sản phẩm theo Bảng 5. CEV ≤ 0,61% theo công thức của tiêu chuẩn; giá trị hoặc công thức khác cần thỏa thuận.", "Cast-analysis limits under Table 4; product-analysis tolerances under Table 5. CEV ≤ 0.61% using the standard formula; other values or formulae require agreement."], ["CB là cốt bê tông; 500 chỉ giới hạn chảy trên quy định 500 MPa; V là thanh vằn.", "CB denotes concrete reinforcement; 500 specifies 500 MPa upper yield strength; V denotes ribbed bars."], ["A₅ ≥ 14% là giãn dài sau đứt với L₀ = 5d; Agt ≥ 8% là giãn dài tổng tại lực lớn nhất. Chọn A hoặc Agt theo thỏa thuận; nếu không quy định riêng, nên chọn Agt. Không coi cả hai là yêu cầu đồng thời mặc định. Giới hạn chảy dùng ReH; nếu không xuất hiện hiện tượng chảy thì xác định Rp0,2. Không dùng 500 MPa làm ứng suất thiết kế mặc định.", "A₅ ≥ 14% is elongation after fracture with L₀ = 5d; Agt ≥ 8% is total elongation at maximum force. Select A or Agt by agreement; absent a specific requirement, Agt is preferred. Do not assume both are mandatory simultaneously. Use upper yield strength ReH; determine Rp0.2 if no yield phenomenon occurs. Do not treat 500 MPa as a default design stress."], ["Thép cốt bê tông thanh vằn CB500-V", "CB500-V ribbed concrete-reinforcing steel"], ["Mác thép thanh vằn cốt bê tông theo tiêu chuẩn Việt Nam, giới hạn chảy trên tối thiểu 500 MPa; ký hiệu đầy đủ là CB500-V.", "Vietnamese-standard ribbed concrete-reinforcing steel with minimum upper yield strength of 500 MPa; the full designation is CB500-V."]]);
// 40Cr specimen basis and separate 316 / 316L records.
ENTRIES.push(...[["Bản gốc tiêu chuẩn do Sanon Pipe lưu trữ; Bảng 1–3 và Điều 6.3–6.4.", "Original standard hosted by Sanon Pipe; Tables 1–3 and Clauses 6.3–6.4."], ["Giới hạn phân tích mẻ nấu 1.4401, trang 1; không gán đây là toàn văn tiêu chuẩn hiện hành.", "1.4401 cast-analysis limits, page 1; this is not a full current-standard text."], ["Cơ tính EN theo dạng C/H/P; bảng ASTM A240 riêng.", "EN mechanical properties by C/H/P product form; separate ASTM A240 table."], ["316 (1.4401 / S31600) và 316L (1.4404 / S31603) là hai bản ghi riêng. Theo bảng EN đang tham chiếu, C tối đa lần lượt 0,07% và 0,03%; không tự thay thế hoặc coi là chứng nhận kép.", "316 (1.4401 / S31600) and 316L (1.4404 / S31603) are separate records. Under the referenced EN chemistry tables, maximum C is 0.07% and 0.03%, respectively; do not assume substitution or dual certification."], ["316L carbon thấp giúp giảm nguy cơ nhạy cảm ăn mòn liên hạt sau hàn; không có nghĩa 316L luôn bền hơn hoặc chống mọi dạng ăn mòn tốt hơn 316.", "Low-carbon 316L reduces susceptibility to intergranular corrosion after welding; it does not mean 316L is always stronger or better against every corrosion mode than 316."], ["Thép không gỉ 316", "316 stainless steel"], ["Cơ tính theo Outokumpu Supra 316/4401; thành phần giới hạn theo thyssenkrupp 11/2017. Phiên bản tiêu chuẩn áp dụng cần đối chiếu đơn hàng.", "Mechanical data from Outokumpu Supra 316/4401; chemistry limits from thyssenkrupp 11/2017. Verify the contract standard edition."], ["Tấm / cuộn cán nóng hoặc nguội", "Hot- or cold-rolled plate, sheet and coil"], ["Ủ dung dịch (+AT), dữ liệu theo dạng sản phẩm", "Solution annealed (+AT), data by product form"], ["Thép không gỉ austenite Cr–Ni–Mo, mác 316 / 1.4401; phân biệt với mác carbon thấp 316L / 1.4404.", "Austenitic Cr–Ni–Mo stainless steel, grade 316 / 1.4401; distinct from low-carbon 316L / 1.4404."], ["Thiết bị hóa chất, thực phẩm và bồn chứa", "Chemical and food-processing equipment and storage tanks"], ["Cơ tính EN phụ thuộc dạng C/H/P; bảng ASTM A240 được giữ riêng, không ghép các chỉ tiêu giữa hai hệ tiêu chuẩn.", "EN properties depend on C/H/P product form; the ASTM A240 table is separate. Do not mix requirements between standards."], ["Có tính hàn tốt; với tiết diện dày, Outokumpu ưu tiên mác carbon thấp để hạn chế ăn mòn liên hạt.", "Good weldability; for thicker sections, Outokumpu prefers low-carbon grades to limit intergranular corrosion."], ["Bảng 3: phôi mẫu 25 mm, tôi 850 °C trong dầu và ram 520 °C, nguội nước hoặc dầu. ReL ≥ 785 MPa, Rm ≥ 980 MPa, A ≥ 9%, Z ≥ 45% là yêu cầu trên mẫu nhiệt luyện; không mặc định là cơ tính thanh giao hàng hoặc chi tiết bất kỳ.", "Table 3: 25 mm sample blank, oil quench at 850 °C and temper at 520 °C, cooled in water or oil. ReL ≥ 785 MPa, Rm ≥ 980 MPa, A ≥ 9% and Z ≥ 45% are heat-treated specimen requirements, not assumed properties of an arbitrary delivered bar or component."], ["HBW ≤ 207 áp dụng khi giao hàng ở trạng thái ủ hoặc ram cao theo Điều 6.4.3 và Bảng 3; không ghép độ cứng này với bộ cơ tính mẫu tôi–ram.", "HBW ≤ 207 applies to annealed or high-temperature-tempered delivery under Clause 6.4.3 and Table 3; do not combine this hardness with the quenched-and-tempered specimen properties."], ["Bảng 3 quy định KU₂ ≥ 47 J (khía U), không phải KV khía V; sổ tay không chuyển đổi hai phép thử.", "Table 3 specifies KU₂ ≥ 47 J (U-notch), not V-notch KV; the handbook does not convert between the tests."], ["Thành phần theo Bảng 1; P, S ≤ 0,030% cho cấp chất lượng thông thường ở Bảng 2. Cấp cao hơn có giới hạn riêng; Cu ≤ 0,20% nếu dùng gia công áp lực nóng.", "Chemistry follows Table 1; P and S ≤ 0.030% for the ordinary quality level in Table 2. Higher quality levels have separate limits; Cu ≤ 0.20% for hot pressure working."], ["Mẫu thử tôi và ram, phôi 25 mm", "Quenched and tempered test specimen, 25 mm blank"], ["Giao hàng ủ hoặc ram cao", "Annealed or high-temperature-tempered delivery"], ["Mẫu nhiệt luyện, phôi 25 mm", "Heat-treated specimen, 25 mm blank"], ["Thép hợp kim cơ khí 40Cr", "40Cr alloy engineering steel"], ["Thép hợp kim cơ khí 40Cr (+QT)", "40Cr alloy engineering steel (+QT)"], ["Mẫu thử tôi và ram, phôi 25 mm (+QT)", "Quenched and tempered test specimen, 25 mm blank (+QT)"], ["+QT — Mẫu thử tôi và ram, phôi 25 mm", "+QT — Quenched and tempered test specimen, 25 mm blank"], ["Thép hợp kim cơ khí 40Cr (+A)", "40Cr alloy engineering steel (+A)"], ["Giao hàng ủ hoặc ram cao (+A)", "Annealed or high-temperature-tempered delivery (+A)"], ["+A — Giao hàng ủ hoặc ram cao", "+A — Annealed or high-temperature-tempered delivery"], ["Trục, bánh răng và chi tiết máy theo thiết kế", "Shafts, gears and machine components according to design"], ["Đối chiếu trực tiếp GB/T 3077-2015, Bảng 1–3, Điều 6.3–6.4; điều kiện nghiệm thu theo hợp đồng.", "Reviewed against GB/T 3077-2015, Tables 1–3 and Clauses 6.3–6.4; acceptance conditions follow the contract."], ["Thép thanh cán nóng hoặc rèn", "Hot-rolled or forged steel bars"], ["Thép hợp kim crom khoảng 0,40% carbon dùng cho chế tạo máy; phân biệt mẫu thử tôi–ram với trạng thái thanh giao hàng.", "Chromium-alloy engineering steel with about 0.40% carbon; distinguish the quenched-and-tempered test specimen from delivered-bar condition."], ["Bảng 3 và Điều 6.4 có quy định riêng về kích thước thanh và chuẩn bị mẫu; cần kiểm tra trước khi nghiệm thu chi tiết hoặc thanh kích thước lớn.", "Table 3 and Clause 6.4 contain bar-size and specimen-preparation provisions; review them before accepting components or large bars."], ["Tôi phôi mẫu theo Bảng 3", "Quench the sample blank under Table 3"], ["Ram phôi mẫu theo Bảng 3", "Temper the sample blank under Table 3"], ["Giới hạn chảy ReL", "Lower yield strength ReL"], ["Dạng sản phẩm (EN)", "Product form (EN)"], ["Cuộn/tấm cán nguội", "Cold-rolled coil/sheet"], ["Cuộn/tấm cán nguội (C)", "Cold-rolled coil/sheet (C)"], ["Cuộn/tấm cán nguội (H)", "Cold-rolled coil/sheet (H)"], ["Cuộn/tấm cán nguội (P)", "Cold-rolled coil/sheet (P)"], ["Cuộn/tấm cán nóng", "Hot-rolled coil/sheet"], ["Cuộn/tấm cán nóng (C)", "Hot-rolled coil/sheet (C)"], ["Cuộn/tấm cán nóng (H)", "Hot-rolled coil/sheet (H)"], ["Cuộn/tấm cán nóng (P)", "Hot-rolled coil/sheet (P)"], ["Tấm dày (quarto)", "Quarto plate"], ["Tấm dày (quarto) (C)", "Quarto plate (C)"], ["Tấm dày (quarto) (H)", "Quarto plate (H)"], ["Tấm dày (quarto) (P)", "Quarto plate (P)"], ["Thẻ số liệu và bảng cơ tính theo dạng C từ dữ liệu Outokumpu. Bảng ASTM được trình bày riêng.", "Cards and mechanical properties use form C from Outokumpu data. The ASTM table is presented separately."], ["Dạng C · theo bảng EN của Outokumpu", "Form C · Outokumpu EN table"], ["Thẻ số liệu và bảng cơ tính theo dạng H từ dữ liệu Outokumpu. Bảng ASTM được trình bày riêng.", "Cards and mechanical properties use form H from Outokumpu data. The ASTM table is presented separately."], ["Dạng H · theo bảng EN của Outokumpu", "Form H · Outokumpu EN table"], ["Thẻ số liệu và bảng cơ tính theo dạng P từ dữ liệu Outokumpu. Bảng ASTM được trình bày riêng.", "Cards and mechanical properties use form P from Outokumpu data. The ASTM table is presented separately."], ["Dạng P · theo bảng EN của Outokumpu", "Form P · Outokumpu EN table"]]);
// Separate ASTM A240 Type 304 / 316 / 316L flat-product records.
ENTRIES.push(...[["Tài liệu Atlas Steels, bản tổng hợp 2013: bảng thành phần, cơ tính ASTM A240/A240M cho sản phẩm cán phẳng. Không coi ngày tải lên là năm phiên bản tiêu chuẩn.", "Atlas Steels compilation, 2013: ASTM A240/A240M chemistry and mechanical tables for flat-rolled products. Upload date is not the standard edition."], ["Áp dụng cho tấm, lá và dải thép không gỉ cán phẳng theo ASTM A240/A240M, trạng thái ủ. Không dùng bản ghi này làm dữ liệu cho thanh ASTM A276 hoặc ống ASTM A312.", "Applies to annealed stainless flat-rolled plate, sheet and strip under ASTM A240/A240M. Do not use this record as ASTM A276 bar or ASTM A312 pipe data."], ["Giới hạn tham khảo theo tài liệu hãng dẫn ASTM A240/A240M; chưa đối chiếu toàn văn phiên bản áp dụng của đơn hàng. Kiểm tra phiên bản, chiều dày, mẫu thử và chứng chỉ trước khi nghiệm thu.", "Reference limits from manufacturer data citing ASTM A240/A240M; the full contract edition has not been reviewed. Check edition, thickness, specimens and certificates before acceptance."], ["Độ giãn dài A50 theo chiều dài đo 50 mm. Yêu cầu mẫu thử, chiều dày và các ngoại lệ phải kiểm tra theo phiên bản A240/A480 áp dụng; không đổi A50 thành A5 hoặc A80.", "Elongation A50 uses a 50 mm gauge length. Check specimen, thickness and exceptions under the applicable A240/A480 edition; do not substitute A5 or A80 for A50."], ["Đây là bản ghi ASTM riêng; không ghép cơ tính hoặc giới hạn hóa học với các bản ghi EN 10088-2 trong sổ tay.", "This is a separate ASTM record; do not combine its mechanical or chemical limits with EN 10088-2 records in the handbook."], ["Theo bảng ASTM tham khảo: Type 316 có C ≤ 0,08%, Type 316L có C ≤ 0,030%. 316L carbon thấp giúp hạn chế nhạy cảm ăn mòn liên hạt sau hàn; không mặc định hai mác thay thế hoặc được chứng nhận kép.", "In the referenced ASTM tables, Type 316 has C ≤ 0.08% and Type 316L has C ≤ 0.030%. Low-carbon 316L reduces susceptibility to intergranular corrosion after welding; substitution or dual certification is not automatic."], ["Tấm, lá và dải inox cho thiết bị và kết cấu theo thiết kế", "Stainless plate, sheet and strip for equipment and structures according to design"], ["Độ cứng tối đa theo bảng tham khảo: 201 HB hoặc 92 HRB; đây là hai thang thử, không cộng gộp và không tự quy đổi.", "Maximum hardness in the reference table: 201 HB or 92 HRB; these are different test scales, not additive or automatically converted."], ["Độ giãn dài A50 theo chiều dài đo 50 mm. Yêu cầu mẫu thử, chiều dày và các ngoại lệ phải kiểm tra theo phiên bản A240/A480 áp dụng; không đổi A50 thành A5 hoặc A80. Giới hạn tham khảo theo tài liệu hãng dẫn ASTM A240/A240M; chưa đối chiếu toàn văn phiên bản áp dụng của đơn hàng. Kiểm tra phiên bản, chiều dày, mẫu thử và chứng chỉ trước khi nghiệm thu.", "Elongation A50 uses a 50 mm gauge length. Check specimen, thickness and exceptions under the applicable A240/A480 edition; do not substitute A5 or A80 for A50. Reference limits from manufacturer data citing ASTM A240/A240M; the full contract edition has not been reviewed. Check edition, thickness, specimens and certificates before acceptance."], ["Thép không gỉ ASTM A240 Type 304", "ASTM A240 Type 304 stainless steel"], ["Tấm, lá và dải thép cán phẳng", "Flat-rolled plate, sheet and strip"], ["Trạng thái ủ theo tiêu chuẩn sản phẩm", "Annealed condition under the product specification"], ["Thép không gỉ austenite Type 304, UNS S30400, dữ liệu riêng theo ASTM A240/A240M cho sản phẩm cán phẳng.", "Austenitic stainless Type 304, UNS S30400, with separate ASTM A240/A240M data for flat-rolled products."], ["Sản phẩm cán phẳng, trạng thái ủ", "Annealed flat-rolled product"], ["Độ cứng tối đa theo bảng tham khảo: 217 HB hoặc 95 HRB; đây là hai thang thử, không cộng gộp và không tự quy đổi.", "Maximum hardness in the reference table: 217 HB or 95 HRB; these are different test scales, not additive or automatically converted."], ["Thép không gỉ ASTM A240 Type 316", "ASTM A240 Type 316 stainless steel"], ["Thép không gỉ austenite Type 316, UNS S31600, dữ liệu riêng theo ASTM A240/A240M cho sản phẩm cán phẳng.", "Austenitic stainless Type 316, UNS S31600, with separate ASTM A240/A240M data for flat-rolled products."], ["Thép không gỉ ASTM A240 Type 316L", "ASTM A240 Type 316L stainless steel"], ["Thép không gỉ austenite Type 316L, UNS S31603, dữ liệu riêng theo ASTM A240/A240M cho sản phẩm cán phẳng.", "Austenitic stainless Type 316L, UNS S31603, with separate ASTM A240/A240M data for flat-rolled products."], ["Độ giãn dài A50", "Elongation A50"]]);
// JIS SUS304 / SUS316 / SUS316L, distinct chemistry and test basis.
ENTRIES.push(...[["Bảng JIS G 4304 / G 4305 cho sản phẩm cán phẳng; không dùng bảng ASTM ở cùng trang thay cho JIS.", "JIS G 4304 / G 4305 flat-product tables; do not substitute the ASTM tables on the same page."], ["Bảng thành phần và cơ tính trạng thái ủ dung dịch; bảng cơ tính dẫn JIS G 4305(2012).", "Chemistry and solution-treated mechanical tables; the mechanical table cites JIS G 4305(2012)."], ["Bảng đối chiếu các mác SUS, cơ tính và các thang độ cứng HB, HRB, HV.", "SUS-grade reference table with mechanical properties and HB, HRB and HV hardness scales."], ["Bản ghi JIS cho tấm, lá và dải inox: JIS G 4304 cán nóng, JIS G 4305 cán nguội, trạng thái ủ dung dịch. Thanh và ống cần tiêu chuẩn sản phẩm riêng.", "JIS record for solution-treated stainless plate, sheet and strip: JIS G 4304 hot rolled and JIS G 4305 cold rolled. Bars and pipes require their own product standards."], ["Số liệu tham khảo từ bảng hãng; bảng Myodo dẫn JIS G 4305(2012). Cần đối chiếu phiên bản tiêu chuẩn, chiều dày và chứng chỉ áp dụng cho đơn hàng.", "Reference data from manufacturer tables; Myodo cites JIS G 4305(2012). Verify the standard edition, thickness and certificate applicable to the order."], ["A ≥ 40% theo bảng JIS tham khảo; loại mẫu thử và chiều dài đo phụ thuộc tiêu chuẩn, chiều dày và dạng sản phẩm. Không mặc định đây là A50 của ASTM hoặc A5 của EN.", "A ≥ 40% in the referenced JIS table; specimen type and gauge length depend on the standard, thickness and product form. Do not assume ASTM A50 or EN A5."], ["Bảng hãng nêu tối đa 187 HB, 90 HRB hoặc 200 HV. Đây là các thang thử riêng, không phải ba phép quy đổi chính xác cho mọi lô thép.", "Manufacturer tables list maxima of 187 HB, 90 HRB or 200 HV. These are separate hardness scales, not exact conversions for every steel batch."], ["SUS316L theo bảng JIS có Ni 12,00–15,00%; Type 316L theo bảng ASTM A240 trong sổ tay có Ni 10,00–14,00%. Không tự coi SUS316L và Type 316L là cùng bộ giới hạn nghiệm thu.", "The referenced JIS SUS316L table specifies Ni 12.00–15.00%; the ASTM A240 Type 316L record specifies Ni 10.00–14.00%. Do not assume identical acceptance limits."], ["A ≥ 40% theo bảng JIS tham khảo; loại mẫu thử và chiều dài đo phụ thuộc tiêu chuẩn, chiều dày và dạng sản phẩm. Không mặc định đây là A50 của ASTM hoặc A5 của EN. Số liệu tham khảo từ bảng hãng; bảng Myodo dẫn JIS G 4305(2012). Cần đối chiếu phiên bản tiêu chuẩn, chiều dày và chứng chỉ áp dụng cho đơn hàng.", "A ≥ 40% in the referenced JIS table; specimen type and gauge length depend on the standard, thickness and product form. Do not assume ASTM A50 or EN A5. Reference data from manufacturer tables; Myodo cites JIS G 4305(2012). Verify the standard edition, thickness and certificate applicable to the order."], ["Thép không gỉ SUS304 (JIS)", "SUS304 stainless steel (JIS)"], ["Tấm, lá và dải cán nóng hoặc cán nguội", "Hot- or cold-rolled plate, sheet and strip"], ["Ủ dung dịch", "Solution treated"], ["Mác inox austenite SUS304 theo JIS; dữ liệu riêng cho sản phẩm cán phẳng ở trạng thái ủ dung dịch.", "JIS austenitic stainless grade SUS304; separate data for solution-treated flat-rolled products."], ["Tấm và chi tiết inox theo thiết kế và môi trường sử dụng", "Stainless sheet and components selected for the design and service environment"], ["Sản phẩm cán phẳng, ủ dung dịch", "Solution-treated flat-rolled product"], ["Thép không gỉ SUS316 (JIS)", "SUS316 stainless steel (JIS)"], ["Mác inox austenite SUS316 theo JIS; dữ liệu riêng cho sản phẩm cán phẳng ở trạng thái ủ dung dịch.", "JIS austenitic stainless grade SUS316; separate data for solution-treated flat-rolled products."], ["Thép không gỉ SUS316L (JIS)", "SUS316L stainless steel (JIS)"], ["Mác inox austenite SUS316L theo JIS; dữ liệu riêng cho sản phẩm cán phẳng ở trạng thái ủ dung dịch.", "JIS austenitic stainless grade SUS316L; separate data for solution-treated flat-rolled products."]]);
// Declared cross-standard references; no material-family fallback.
ENTRIES.push(...[["Bảng đối chiếu JIS / EN / UNS; JSSA không bảo đảm các mác có cùng mọi yêu cầu hoặc được thay thế trực tiếp.", "JIS / EN / UNS comparison table; JSSA does not guarantee identical requirements or direct substitution."], ["Đối chiếu tên mác theo bảng JSSA. Cần kiểm tra thành phần, cơ tính, dạng sản phẩm và điều kiện sử dụng trước khi thay thế.", "Grade-designation comparison based on the JSSA table. Check chemistry, mechanical properties, product form and service conditions before substitution."], ["Mác gốc đứng đầu. Chỉ liệt kê các mác có quan hệ đối chiếu được khai báo; cùng phân nhóm vật liệu không đủ để xác định mác tương ứng.", "The original grade appears first. Only declared cross-references are listed; sharing a material subgroup does not establish corresponding grades."], ["Đối chiếu tên mác · tham khảo", "Grade cross-reference · reference only"], ["2. Các mác đối chiếu theo hệ tiêu chuẩn", "2. Cross-referenced grades by standard system"], ["Chưa có quan hệ đối chiếu được khai báo cho mác này.", "No grade cross-reference has been declared for this material."]]);
// Existing reference records resolve to clickable material counterparts.
ENTRIES.push(...[["Chưa có bản ghi trong HB", "No handbook record yet"], ["3. Mác tham khảo chưa có dữ liệu trong HB", "3. Reference grades without handbook records"], ["Các mác này chưa có bản ghi để mở bảng đối chiếu. Danh sách chỉ giữ thông tin tham khảo từ nguồn.", "These grades have no handbook record for opening a comparison. The list retains source reference information only."]]);
// Whole-catalogue equivalence audit: distinguish missing and incompatible records.
ENTRIES.push(...[["Chưa có bản ghi phù hợp trong HB", "No matching handbook record yet"], ["Chưa tìm được bản ghi khớp mác và tiêu chuẩn tham chiếu. Danh sách giữ thông tin từ nguồn; không tự nối sang mác khác hoặc tiêu chuẩn khác.", "No record matching the grade and referenced standard was found. Source information is retained; other grades or standards are not linked automatically."]]);
// Common JIS cast irons: specimen basis, unknown chemistry, indicative hardness.
ENTRIES.push(...[["Bảng cơ tính gang xám và gang cầu; độ cứng gang cầu được ghi là tham khảo.", "Grey- and ductile-iron mechanical tables; ductile-iron hardness is explicitly indicative."], ["Bảng cho mẫu đúc rời, trang 2; không phải bảng mẫu đúc kèm hoặc mẫu lấy trực tiếp từ vật đúc. Phiên bản JIS không ghi rõ trong bản trích.", "Separately cast sample table, page 2; not a cast-on or casting-extracted specimen table. The extract does not identify the JIS edition."], ["Bản xem trước tiêu chuẩn, lưu trên Normsplash; không gán là toàn văn phiên bản hiện hành.", "Standard preview hosted by Normsplash; not presented as the complete current edition."], ["Dữ liệu tham khảo theo bảng hãng dẫn JIS; phiên bản tiêu chuẩn, mẫu thử và điều kiện nghiệm thu phải đối chiếu theo đơn hàng.", "Reference data from manufacturer tables citing JIS; verify standard edition, specimens and acceptance conditions against the order."], ["Nguồn đang dùng phân cấp theo cơ tính, không cung cấp bộ giới hạn thành phần để nghiệm thu từng mác. Không tự gán khoảng C, Si, Mn, P hoặc S; kiểm tra chứng chỉ mẻ nấu và yêu cầu đơn hàng.", "The reference grades are classified by mechanical properties and do not provide per-grade chemistry acceptance limits. Do not assign C, Si, Mn, P or S ranges; check heat certificates and order requirements."], ["Rm theo mẫu đúc rời, Bảng 2 JIS G 5501:1995 trong nguồn tham khảo; không bảo đảm mọi vị trí của vật đúc có cùng Rm. Mẫu đúc kèm hoặc lấy từ thân vật đúc có bảng riêng; cần thống nhất loại mẫu và chiều dày thành.", "Rm follows separately cast samples in Table 2 of the referenced JIS G 5501:1995 preview; it is not guaranteed at every casting location. Cast-on or casting-extracted specimens use separate tables; agree specimen type and wall thickness."], ["Cơ tính theo mẫu đúc rời trong bảng trích JIS G 5502. Mẫu đúc kèm hoặc lấy từ thân vật đúc, chiều dày thành và trạng thái nhiệt luyện có thể cho yêu cầu khác; cần đối chiếu đúng loại mẫu.", "Mechanical properties follow separately cast samples in the JIS G 5502 extract. Cast-on or casting-extracted specimens, wall thickness and heat treatment can have different requirements; use the correct specimen basis."], ["Không có Re/Rp0,2, A hoặc KV trong bảng đang tham chiếu cho các mác FC này; không suy ra từ số FC hoặc từ Rm.", "The referenced FC table specifies no Re/Rp0.2, A or KV; do not derive them from the FC number or Rm."], ["Bảng không quy định Charpy cho cấp mác này. Không dùng yêu cầu va đập của các mác FCD có hậu tố L hoặc R để thay thế.", "The table specifies no Charpy requirement for this grade. Do not substitute impact requirements from FCD grades with L or R suffixes."], ["Không tự coi mác gang FC/FCD khác cấp hoặc mác EN/ASTM có cùng số là tương đương; chỉ hiện liên kết khi có quan hệ đối chiếu được khai báo.", "Do not assume equivalence between different FC/FCD grades or EN/ASTM grades with matching numbers; links require a declared cross-reference."], ["Bảng tham khảo nêu độ cứng tối đa 223 HB; JIS G 5501:1995 áp dụng yêu cầu độ cứng khi người mua yêu cầu riêng. Cần thống nhất phép thử và vị trí đo; không coi đây là độ cứng cố định của mọi vật đúc.", "The reference table lists maximum hardness of 223 HB; JIS G 5501:1995 applies hardness requirements when specifically requested by the purchaser. Agree testing and measurement locations; this is not a fixed hardness for every casting."], ["Rm theo mẫu đúc rời, Bảng 2 JIS G 5501:1995 trong nguồn tham khảo; không bảo đảm mọi vị trí của vật đúc có cùng Rm. Mẫu đúc kèm hoặc lấy từ thân vật đúc có bảng riêng; cần thống nhất loại mẫu và chiều dày thành. Không có Re/Rp0,2, A hoặc KV trong bảng đang tham chiếu cho các mác FC này; không suy ra từ số FC hoặc từ Rm. Bảng tham khảo nêu độ cứng tối đa 223 HB; JIS G 5501:1995 áp dụng yêu cầu độ cứng khi người mua yêu cầu riêng. Cần thống nhất phép thử và vị trí đo; không coi đây là độ cứng cố định của mọi vật đúc.", "Rm follows separately cast samples in Table 2 of the referenced JIS G 5501:1995 preview; it is not guaranteed at every casting location. Cast-on or casting-extracted specimens use separate tables; agree specimen type and wall thickness. The referenced FC table specifies no Re/Rp0.2, A or KV; do not derive them from the FC number or Rm. The reference table lists maximum hardness of 223 HB; JIS G 5501:1995 applies hardness requirements when specifically requested by the purchaser. Agree testing and measurement locations; this is not a fixed hardness for every casting."], ["Gang xám FC200", "FC200 grey cast iron"], ["Chi tiết gang xám đúc", "Grey iron castings"], ["Trạng thái vật đúc theo đơn hàng", "Casting condition according to the order"], ["Gang xám graphit dạng tấm, mác FC200; mức bền kéo 200 MPa theo bảng tham khảo, thích hợp tra cứu vật liệu đúc.", "Flake-graphite grey iron grade FC200; 200 MPa tensile grade level in the reference table, for casting-material lookup."], ["Thân máy, vỏ hộp và thân bơm theo thiết kế vật đúc", "Machine bodies, housings and pump bodies according to casting design"], ["Mẫu đúc rời", "Separately cast sample"], ["Bảng tham khảo nêu độ cứng tối đa 241 HB; JIS G 5501:1995 áp dụng yêu cầu độ cứng khi người mua yêu cầu riêng. Cần thống nhất phép thử và vị trí đo; không coi đây là độ cứng cố định của mọi vật đúc.", "The reference table lists maximum hardness of 241 HB; JIS G 5501:1995 applies hardness requirements when specifically requested by the purchaser. Agree testing and measurement locations; this is not a fixed hardness for every casting."], ["Rm theo mẫu đúc rời, Bảng 2 JIS G 5501:1995 trong nguồn tham khảo; không bảo đảm mọi vị trí của vật đúc có cùng Rm. Mẫu đúc kèm hoặc lấy từ thân vật đúc có bảng riêng; cần thống nhất loại mẫu và chiều dày thành. Không có Re/Rp0,2, A hoặc KV trong bảng đang tham chiếu cho các mác FC này; không suy ra từ số FC hoặc từ Rm. Bảng tham khảo nêu độ cứng tối đa 241 HB; JIS G 5501:1995 áp dụng yêu cầu độ cứng khi người mua yêu cầu riêng. Cần thống nhất phép thử và vị trí đo; không coi đây là độ cứng cố định của mọi vật đúc.", "Rm follows separately cast samples in Table 2 of the referenced JIS G 5501:1995 preview; it is not guaranteed at every casting location. Cast-on or casting-extracted specimens use separate tables; agree specimen type and wall thickness. The referenced FC table specifies no Re/Rp0.2, A or KV; do not derive them from the FC number or Rm. The reference table lists maximum hardness of 241 HB; JIS G 5501:1995 applies hardness requirements when specifically requested by the purchaser. Agree testing and measurement locations; this is not a fixed hardness for every casting."], ["Gang xám FC250", "FC250 grey cast iron"], ["Gang xám graphit dạng tấm, mác FC250; mức bền kéo 250 MPa theo bảng tham khảo, thích hợp tra cứu vật liệu đúc.", "Flake-graphite grey iron grade FC250; 250 MPa tensile grade level in the reference table, for casting-material lookup."], ["Bảng tham khảo nêu độ cứng tối đa 262 HB; JIS G 5501:1995 áp dụng yêu cầu độ cứng khi người mua yêu cầu riêng. Cần thống nhất phép thử và vị trí đo; không coi đây là độ cứng cố định của mọi vật đúc.", "The reference table lists maximum hardness of 262 HB; JIS G 5501:1995 applies hardness requirements when specifically requested by the purchaser. Agree testing and measurement locations; this is not a fixed hardness for every casting."], ["Rm theo mẫu đúc rời, Bảng 2 JIS G 5501:1995 trong nguồn tham khảo; không bảo đảm mọi vị trí của vật đúc có cùng Rm. Mẫu đúc kèm hoặc lấy từ thân vật đúc có bảng riêng; cần thống nhất loại mẫu và chiều dày thành. Không có Re/Rp0,2, A hoặc KV trong bảng đang tham chiếu cho các mác FC này; không suy ra từ số FC hoặc từ Rm. Bảng tham khảo nêu độ cứng tối đa 262 HB; JIS G 5501:1995 áp dụng yêu cầu độ cứng khi người mua yêu cầu riêng. Cần thống nhất phép thử và vị trí đo; không coi đây là độ cứng cố định của mọi vật đúc.", "Rm follows separately cast samples in Table 2 of the referenced JIS G 5501:1995 preview; it is not guaranteed at every casting location. Cast-on or casting-extracted specimens use separate tables; agree specimen type and wall thickness. The referenced FC table specifies no Re/Rp0.2, A or KV; do not derive them from the FC number or Rm. The reference table lists maximum hardness of 262 HB; JIS G 5501:1995 applies hardness requirements when specifically requested by the purchaser. Agree testing and measurement locations; this is not a fixed hardness for every casting."], ["Gang xám FC300", "FC300 grey cast iron"], ["Gang xám graphit dạng tấm, mác FC300; mức bền kéo 300 MPa theo bảng tham khảo, thích hợp tra cứu vật liệu đúc.", "Flake-graphite grey iron grade FC300; 300 MPa tensile grade level in the reference table, for casting-material lookup."], ["Độ cứng 130–180 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB.", "Hardness 130–180 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB."], ["Trong ký hiệu FCD400-15, 400 là mức bền kéo tối thiểu và 15 là độ giãn dài tối thiểu của cấp mác trên mẫu thử quy định.", "In FCD400-15, 400 denotes the minimum tensile grade level and 15 the minimum elongation on the specified test specimen."], ["Cơ tính theo mẫu đúc rời trong bảng trích JIS G 5502. Mẫu đúc kèm hoặc lấy từ thân vật đúc, chiều dày thành và trạng thái nhiệt luyện có thể cho yêu cầu khác; cần đối chiếu đúng loại mẫu. Độ cứng 130–180 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB. Dữ liệu tham khảo theo bảng hãng dẫn JIS; phiên bản tiêu chuẩn, mẫu thử và điều kiện nghiệm thu phải đối chiếu theo đơn hàng.", "Mechanical properties follow separately cast samples in the JIS G 5502 extract. Cast-on or casting-extracted specimens, wall thickness and heat treatment can have different requirements; use the correct specimen basis. Hardness 130–180 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB. Reference data from manufacturer tables citing JIS; verify standard edition, specimens and acceptance conditions against the order."], ["Gang cầu FCD400-15", "FCD400-15 ductile cast iron"], ["Chi tiết gang graphit cầu đúc", "Spheroidal graphite iron castings"], ["Trạng thái chế tạo đạt cơ tính theo đơn hàng", "Manufacturing condition meeting the ordered mechanical properties"], ["Gang graphit cầu FCD400-15; dữ liệu Re/Rm/A của mẫu đúc rời, khác gang xám FC và khác các cấp FCD cùng họ.", "Spheroidal graphite iron FCD400-15; yield, tensile and elongation data for separately cast samples, distinct from FC grey iron and other FCD grades."], ["Chi tiết gang cầu chịu tải theo thiết kế vật đúc", "Load-carrying ductile-iron components according to casting design"], ["Độ cứng 140–210 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB.", "Hardness 140–210 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB."], ["Trong ký hiệu FCD450-10, 450 là mức bền kéo tối thiểu và 10 là độ giãn dài tối thiểu của cấp mác trên mẫu thử quy định.", "In FCD450-10, 450 denotes the minimum tensile grade level and 10 the minimum elongation on the specified test specimen."], ["Cơ tính theo mẫu đúc rời trong bảng trích JIS G 5502. Mẫu đúc kèm hoặc lấy từ thân vật đúc, chiều dày thành và trạng thái nhiệt luyện có thể cho yêu cầu khác; cần đối chiếu đúng loại mẫu. Độ cứng 140–210 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB. Dữ liệu tham khảo theo bảng hãng dẫn JIS; phiên bản tiêu chuẩn, mẫu thử và điều kiện nghiệm thu phải đối chiếu theo đơn hàng.", "Mechanical properties follow separately cast samples in the JIS G 5502 extract. Cast-on or casting-extracted specimens, wall thickness and heat treatment can have different requirements; use the correct specimen basis. Hardness 140–210 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB. Reference data from manufacturer tables citing JIS; verify standard edition, specimens and acceptance conditions against the order."], ["Gang cầu FCD450-10", "FCD450-10 ductile cast iron"], ["Gang graphit cầu FCD450-10; dữ liệu Re/Rm/A của mẫu đúc rời, khác gang xám FC và khác các cấp FCD cùng họ.", "Spheroidal graphite iron FCD450-10; yield, tensile and elongation data for separately cast samples, distinct from FC grey iron and other FCD grades."], ["Độ cứng 150–230 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB.", "Hardness 150–230 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB."], ["Trong ký hiệu FCD500-7, 500 là mức bền kéo tối thiểu và 7 là độ giãn dài tối thiểu của cấp mác trên mẫu thử quy định.", "In FCD500-7, 500 denotes the minimum tensile grade level and 7 the minimum elongation on the specified test specimen."], ["Cơ tính theo mẫu đúc rời trong bảng trích JIS G 5502. Mẫu đúc kèm hoặc lấy từ thân vật đúc, chiều dày thành và trạng thái nhiệt luyện có thể cho yêu cầu khác; cần đối chiếu đúng loại mẫu. Độ cứng 150–230 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB. Dữ liệu tham khảo theo bảng hãng dẫn JIS; phiên bản tiêu chuẩn, mẫu thử và điều kiện nghiệm thu phải đối chiếu theo đơn hàng.", "Mechanical properties follow separately cast samples in the JIS G 5502 extract. Cast-on or casting-extracted specimens, wall thickness and heat treatment can have different requirements; use the correct specimen basis. Hardness 150–230 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB. Reference data from manufacturer tables citing JIS; verify standard edition, specimens and acceptance conditions against the order."], ["Gang cầu FCD500-7", "FCD500-7 ductile cast iron"], ["Gang graphit cầu FCD500-7; dữ liệu Re/Rm/A của mẫu đúc rời, khác gang xám FC và khác các cấp FCD cùng họ.", "Spheroidal graphite iron FCD500-7; yield, tensile and elongation data for separately cast samples, distinct from FC grey iron and other FCD grades."], ["Độ cứng 170–270 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB.", "Hardness 170–270 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB."], ["Trong ký hiệu FCD600-3, 600 là mức bền kéo tối thiểu và 3 là độ giãn dài tối thiểu của cấp mác trên mẫu thử quy định.", "In FCD600-3, 600 denotes the minimum tensile grade level and 3 the minimum elongation on the specified test specimen."], ["Cơ tính theo mẫu đúc rời trong bảng trích JIS G 5502. Mẫu đúc kèm hoặc lấy từ thân vật đúc, chiều dày thành và trạng thái nhiệt luyện có thể cho yêu cầu khác; cần đối chiếu đúng loại mẫu. Độ cứng 170–270 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB. Dữ liệu tham khảo theo bảng hãng dẫn JIS; phiên bản tiêu chuẩn, mẫu thử và điều kiện nghiệm thu phải đối chiếu theo đơn hàng.", "Mechanical properties follow separately cast samples in the JIS G 5502 extract. Cast-on or casting-extracted specimens, wall thickness and heat treatment can have different requirements; use the correct specimen basis. Hardness 170–270 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB. Reference data from manufacturer tables citing JIS; verify standard edition, specimens and acceptance conditions against the order."], ["Gang cầu FCD600-3", "FCD600-3 ductile cast iron"], ["Gang graphit cầu FCD600-3; dữ liệu Re/Rm/A của mẫu đúc rời, khác gang xám FC và khác các cấp FCD cùng họ.", "Spheroidal graphite iron FCD600-3; yield, tensile and elongation data for separately cast samples, distinct from FC grey iron and other FCD grades."], ["Độ cứng 180–300 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB.", "Hardness 180–300 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB."], ["Trong ký hiệu FCD700-2, 700 là mức bền kéo tối thiểu và 2 là độ giãn dài tối thiểu của cấp mác trên mẫu thử quy định.", "In FCD700-2, 700 denotes the minimum tensile grade level and 2 the minimum elongation on the specified test specimen."], ["Cơ tính theo mẫu đúc rời trong bảng trích JIS G 5502. Mẫu đúc kèm hoặc lấy từ thân vật đúc, chiều dày thành và trạng thái nhiệt luyện có thể cho yêu cầu khác; cần đối chiếu đúng loại mẫu. Độ cứng 180–300 HB là khoảng tham khảo trong bảng, không phải giới hạn nghiệm thu mặc định. Không suy ra Re/Rm/A từ HB. Dữ liệu tham khảo theo bảng hãng dẫn JIS; phiên bản tiêu chuẩn, mẫu thử và điều kiện nghiệm thu phải đối chiếu theo đơn hàng.", "Mechanical properties follow separately cast samples in the JIS G 5502 extract. Cast-on or casting-extracted specimens, wall thickness and heat treatment can have different requirements; use the correct specimen basis. Hardness 180–300 HB is an indicative range in the table, not a default acceptance limit. Do not infer yield, tensile strength or elongation from HB. Reference data from manufacturer tables citing JIS; verify standard edition, specimens and acceptance conditions against the order."], ["Gang cầu FCD700-2", "FCD700-2 ductile cast iron"], ["Gang graphit cầu FCD700-2; dữ liệu Re/Rm/A của mẫu đúc rời, khác gang xám FC và khác các cấp FCD cùng họ.", "Spheroidal graphite iron FCD700-2; yield, tensile and elongation data for separately cast samples, distinct from FC grey iron and other FCD grades."], ["Gang xám", "Grey cast iron"], ["Gang cầu", "Ductile cast iron"]]);
// Common aluminium and copper alloys; temper-specific data.
ENTRIES.push(...[["Dữ liệu theo bảng hãng và phiên bản tiêu chuẩn được nguồn viện dẫn; không thay toàn văn tiêu chuẩn áp dụng cho đơn hàng. Kiểm tra trạng thái, dạng sản phẩm, kích thước và chứng chỉ.", "Data follow manufacturer tables and their cited standard editions, not the full contract specification. Check temper, product form, dimensions and certificates."], ["Cơ tính chỉ áp dụng cho trạng thái và dạng sản phẩm đang xem; không dùng cho trạng thái mềm/cứng khác hoặc sản phẩm sau hàn mà chưa đánh giá.", "Properties apply only to the displayed temper and product form; do not transfer them to other tempers or unevaluated welded products."], ["Tấm nhôm cán", "Rolled aluminium sheet"], ["H14 — biến cứng, bán cứng", "H14 — strain hardened, half hard"], ["Bảng tham khảo cho tấm dày 0,2–6 mm. A phụ thuộc chiều dày và mẫu thử; không gán một trị số A cho toàn dải trong bản ghi này.", "Reference table for 0.2–6 mm sheet. Elongation depends on thickness and specimen; no single A value is assigned across the range."], ["Al là phần còn lại; giới hạn nguyên tố theo EN 573-3:2009 được Aalco viện dẫn.", "Al is the balance; element limits follow EN 573-3:2009 as cited by Aalco."], ["Độ cứng khoảng 34 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "Hardness of about 34 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Nhôm 1050A-H14", "Aluminium 1050A-H14"], ["Hợp kim nhôm 1050A, trạng thái H14; số liệu theo dạng sản phẩm và vùng kích thước của nguồn.", "Aluminium alloy 1050A, temper H14; data follow the source product form and size range."], ["Bảng tham khảo cho tấm dày 0,2–6 mm. A phụ thuộc chiều dày và mẫu thử; không gán một trị số A cho toàn dải trong bản ghi này. Độ cứng khoảng 34 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "Reference table for 0.2–6 mm sheet. Elongation depends on thickness and specimen; no single A value is assigned across the range. Hardness of about 34 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Tấm, vỏ và chi tiết tạo hình theo thiết kế", "Sheet, enclosures and formed parts according to design"], ["H32 — biến cứng và ổn định hóa, 1/4 cứng", "H32 — strain hardened and stabilised, quarter hard"], ["Độ cứng khoảng 61 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "Hardness of about 61 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Nhôm 5052-H32", "Aluminium 5052-H32"], ["Hợp kim nhôm 5052, trạng thái H32; số liệu theo dạng sản phẩm và vùng kích thước của nguồn.", "Aluminium alloy 5052, temper H32; data follow the source product form and size range."], ["Bảng tham khảo cho tấm dày 0,2–6 mm. A phụ thuộc chiều dày và mẫu thử; không gán một trị số A cho toàn dải trong bản ghi này. Độ cứng khoảng 61 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "Reference table for 0.2–6 mm sheet. Elongation depends on thickness and specimen; no single A value is assigned across the range. Hardness of about 61 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Thanh tròn nhôm ép đùn đặc", "Solid extruded aluminium round bar"], ["T6 — nhiệt luyện dung dịch và hóa già nhân tạo", "T6 — solution heat treated and artificially aged"], ["Bản ghi chỉ cho thanh tròn đặc d ≤ 200 mm. Không dùng bảng này cho ống hoặc nhôm định hình có chiều dày thành khác.", "This record covers solid round bar up to 200 mm diameter only. Do not use it for tubes or profiles with other wall-thickness requirements."], ["Độ cứng khoảng 95 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "Hardness of about 95 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Nhôm 6061-T6", "Aluminium 6061-T6"], ["Hợp kim nhôm 6061, trạng thái T6; số liệu theo dạng sản phẩm và vùng kích thước của nguồn.", "Aluminium alloy 6061, temper T6; data follow the source product form and size range."], ["Bản ghi chỉ cho thanh tròn đặc d ≤ 200 mm. Không dùng bảng này cho ống hoặc nhôm định hình có chiều dày thành khác. Độ cứng khoảng 95 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "This record covers solid round bar up to 200 mm diameter only. Do not use it for tubes or profiles with other wall-thickness requirements. Hardness of about 95 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Khung và chi tiết nhôm ép đùn theo thiết kế", "Frames and extruded aluminium components according to design"], ["Vùng ảnh hưởng nhiệt sau hàn có thể giảm bền; không giữ nguyên cơ tính T6 của vật liệu nền để nghiệm thu mối hàn.", "Welding can reduce heat-affected-zone strength; parent-metal T6 properties are not retained automatically for weld acceptance."], ["Độ cứng khoảng 75 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "Hardness of about 75 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Nhôm 6063-T6", "Aluminium 6063-T6"], ["Hợp kim nhôm 6063, trạng thái T6; số liệu theo dạng sản phẩm và vùng kích thước của nguồn.", "Aluminium alloy 6063, temper T6; data follow the source product form and size range."], ["Bản ghi chỉ cho thanh tròn đặc d ≤ 200 mm. Không dùng bảng này cho ống hoặc nhôm định hình có chiều dày thành khác. Độ cứng khoảng 75 HB là trị số tham khảo của hãng, không phải giới hạn HB tối thiểu hoặc tối đa.", "This record covers solid round bar up to 200 mm diameter only. Do not use it for tubes or profiles with other wall-thickness requirements. Hardness of about 75 HB is a supplier reference value, not a minimum or maximum HB limit."], ["Dùng cột A trong bảng thanh đặc: A ≥ 10%. Cột A50 ≥ 8% được nguồn nêu riêng cho thanh đến 150 mm; không gộp A và A50. 6063A là mác khác 6063.", "The solid-bar table uses A ≥ 10%. A50 ≥ 8% is separately listed for bar up to 150 mm; do not merge A and A50. 6063A is a different alloy from 6063."], ["Đồng đỏ Cu-ETP", "Cu-ETP copper"], ["Tấm và dải cán", "Rolled sheet and strip"], ["Đồng điện phân có oxy, độ dẫn điện cao; cần xét môi trường và phương pháp gia công.", "Oxygen-bearing electrolytic copper with high conductivity; assess service environment and fabrication method."], ["Số liệu tấm/dải theo trạng thái R trong bảng hãng. Không dùng cho thanh hoặc ống khác tiêu chuẩn. Dải kích thước áp dụng cần đối chiếu chứng chỉ và đơn hàng.", "Rolled sheet/strip data by R temper in the manufacturer table. Do not apply to bars or tubes under other standards. Verify size applicability against the certificate and order."], ["Độ cứng HV chỉ tham khảo, không đổi sang HB. Các trị số Rp0,2 có dấu tham khảo trong nguồn không được coi là giới hạn nghiệm thu.", "HV hardness is indicative and is not converted to HB. Proof-stress values marked as informational in the source are not acceptance limits."], ["Số liệu tấm/dải theo trạng thái R trong bảng hãng. Không dùng cho thanh hoặc ống khác tiêu chuẩn. Dải kích thước áp dụng cần đối chiếu chứng chỉ và đơn hàng. Độ cứng HV chỉ tham khảo, không đổi sang HB. Các trị số Rp0,2 có dấu tham khảo trong nguồn không được coi là giới hạn nghiệm thu.", "Rolled sheet/strip data by R temper in the manufacturer table. Do not apply to bars or tubes under other standards. Verify size applicability against the certificate and order. HV hardness is indicative and is not converted to HB. Proof-stress values marked as informational in the source are not acceptance limits."], ["Mềm, theo cấp bền R220", "Soft, strength temper R220"], ["Đồng đỏ Cu-ETP (R220)", "Cu-ETP copper (R220)"], ["Mềm, theo cấp bền R220 (R220)", "Soft, strength temper R220 (R220)"], ["R220 — Mềm, theo cấp bền R220", "R220 — Soft, strength temper R220"], ["Biến cứng, theo cấp bền R290", "Work hardened, strength temper R290"], ["Đồng đỏ Cu-ETP (R290)", "Cu-ETP copper (R290)"], ["Biến cứng, theo cấp bền R290 (R290)", "Work hardened, strength temper R290 (R290)"], ["R290 — Biến cứng, theo cấp bền R290", "R290 — Work hardened, strength temper R290"], ["Thành phần theo datasheet hãng; không tự đồng nhất các giới hạn EN, UNS và JIS dù nguồn có bảng đối chiếu tên mác.", "Chemistry follows the manufacturer datasheet; EN, UNS and JIS limits are not assumed identical even where cross-designations are listed."], ["Số liệu vật lý tham khảo ở 20 °C/trạng thái mềm theo nguồn; không suy ra độ dẫn điện của mọi trạng thái biến cứng.", "Physical data are references at 20 °C/in the soft condition per source; conductivity is not inferred for every work-hardened temper."], ["Chi tiết dẫn điện hoặc truyền nhiệt theo yêu cầu thiết kế", "Electrical or heat-transfer components according to design"], ["Đồng đỏ Cu-DHP", "Cu-DHP copper"], ["Đồng khử oxy bằng phosphor; khả năng dẫn điện khác đồng ETP và phụ thuộc trạng thái.", "Phosphorus-deoxidised copper; conductivity differs from ETP copper and depends on temper."], ["C1220 (đối chiếu tên mác theo hãng)", "C1220 (manufacturer cross-designation)"], ["Đồng đỏ Cu-DHP (R220)", "Cu-DHP copper (R220)"], ["Đồng đỏ Cu-DHP (R290)", "Cu-DHP copper (R290)"], ["Đồng thau CuZn30", "CuZn30 brass"], ["Đồng thau Cu–Zn, dùng cho tạo hình và dập vuốt; phân biệt trạng thái mềm và biến cứng.", "Cu–Zn brass for forming and deep drawing; distinguish soft and work-hardened tempers."], ["Mềm, theo cấp bền R270", "Soft, strength temper R270"], ["Đồng thau CuZn30 (R270)", "CuZn30 brass (R270)"], ["Mềm, theo cấp bền R270 (R270)", "Soft, strength temper R270 (R270)"], ["R270 — Mềm, theo cấp bền R270", "R270 — Soft, strength temper R270"], ["Biến cứng, theo cấp bền R350", "Work hardened, strength temper R350"], ["Đồng thau CuZn30 (R350)", "CuZn30 brass (R350)"], ["Biến cứng, theo cấp bền R350 (R350)", "Work hardened, strength temper R350 (R350)"], ["R350 — Biến cứng, theo cấp bền R350", "R350 — Work hardened, strength temper R350"], ["Zn là phần còn lại; giới hạn thành phần theo bảng Aalco, cơ tính theo bảng KME. Cu 70% trong KME là thành phần danh nghĩa, không thay giới hạn Cu 69–71%.", "Zn is the balance; chemistry limits follow Aalco and mechanical data follow KME. KME nominal Cu 70% does not replace Cu limits of 69–71%."], ["Chi tiết dập, đầu nối và linh kiện điện theo thiết kế", "Stamped parts, connectors and electrical components according to design"], ["Đồng thau dễ gia công CuZn39Pb3", "CuZn39Pb3 free-machining brass"], ["Bảng Pireks dẫn EN 12164:2024 cho thanh tròn đặc R430: 3 < d ≤ 60 mm. Không dùng cho thanh rỗng, phôi rèn, trạng thái H110 hoặc mọi vật liệu mang tên đồng vàng.", "Pireks references EN 12164:2024 for solid round bar R430: 3 < d ≤ 60 mm. Not applicable to hollow bar, forging stock, H110 or all materials called brass."], ["Thanh tròn đặc để gia công cắt gọt", "Solid round bar for machining"], ["Đồng thau chứa chì để cải thiện cắt gọt; bản ghi cho cấp bền R430 và thanh tròn đặc.", "Leaded brass for improved machinability; this record covers strength temper R430 solid round bar."], ["CZ121 (đối chiếu tham khảo)", "CZ121 (reference cross-designation)"], ["Thành phần dùng cột CW614N thường của Pireks: Pb 2,20–3,50%. Không ghép với cột CW614N-DW hoặc giới hạn từ phiên bản khác; Zn là phần còn lại.", "Chemistry uses the Pireks ordinary CW614N column: Pb 2.20–3.50%. Do not mix with CW614N-DW or other edition limits; Zn is the balance."], ["A ≥ 10% theo cột A; A100 ≥ 6% và A11,3 ≥ 8% là các cột khác. Không gộp các chiều dài mẫu. Không lấy HBW của H110 gán cho trạng thái R430.", "A ≥ 10% follows column A; A100 ≥ 6% and A11.3 ≥ 8% are different columns. Do not merge specimen gauge lengths or assign H110 hardness to R430."], ["Chi tiết tiện, đầu nối và phụ kiện gia công cắt gọt", "Turned parts, connectors and machined fittings"], ["Nhôm và hợp kim", "Aluminium and alloys"], ["Đồng và hợp kim", "Copper and alloys"]]);
// Separate T5 extrusion data; no transfer of T6 values.
ENTRIES.push(...[["Dùng cột mức tối thiểu của T5; không dùng cột điển hình. Chú thích 2 chỉ viện dẫn cơ tính AS/NZS 1866 cho T1, T4, T6.", "Use the T5 minimum-rating columns, not typical values. Note 2 cites AS/NZS 1866 mechanical properties for T1, T4 and T6 only."], ["Bảng hãng viện dẫn AS/NZS 1866:1997, tái xác nhận 2020; phạm vi T5 ghi chiều dày < 12 mm.", "Manufacturer table references AS/NZS 1866:1997, reconfirmed 2020; the T5 thickness range is stated as < 12 mm."], ["T5 — làm nguội sau tạo hình nóng và hóa già nhân tạo", "T5 — cooled after hot shaping and artificially aged"], ["T5 và T6 khác quy trình nhiệt luyện. Không dùng lại cơ tính T6, không tự coi hai trạng thái là tương đương. Cơ tính sau hàn cần đánh giá riêng.", "T5 and T6 use different heat-treatment routes. Do not reuse T6 properties or assume equivalence. Evaluate welded properties separately."], ["Số liệu theo bảng hãng, không thay thế toàn văn tiêu chuẩn hoặc chứng chỉ lô hàng. Kiểm tra trạng thái, kích thước và yêu cầu nghiệm thu theo đơn hàng.", "Manufacturer-table data do not replace the full specification or batch certificate. Check temper, size and order acceptance requirements."], ["Theo McKechnie: t là đường kính thanh đặc, chiều dày thành hoặc tiết diện đặc chi phối tương đương. Chỉ có dữ liệu T5 cho 0 < t ≤ 6 mm; không dùng đường kính ngoài của ống làm t.", "McKechnie defines t as solid-rod diameter, wall thickness or equivalent major solid section. T5 data cover 0 < t ≤ 6 mm only; tube outside diameter is not t."], ["6061-T5 dùng mức tối thiểu/rating của McKechnie. Nguồn chỉ xác nhận T1, T4, T6 theo AS/NZS 1866; không gán bộ cơ tính T5 này thành yêu cầu EN 755-2 hoặc ASTM B221.", "6061-T5 uses McKechnie minimum ratings. The source confirms T1, T4 and T6 under AS/NZS 1866; these T5 ratings are not assigned as EN 755-2 or ASTM B221 requirements."], ["Al là phần còn lại; nguyên tố khác: mỗi nguyên tố ≤ 0,05%, tổng ≤ 0,15% theo bảng nguồn. Thành phần cùng mác không làm cơ tính T5 bằng T6.", "Al is the balance; other elements are each ≤ 0.05% and total ≤ 0.15% in the source table. Shared alloy chemistry does not make T5 properties equal to T6."], ["Theo McKechnie: t là đường kính thanh đặc, chiều dày thành hoặc tiết diện đặc chi phối tương đương. Chỉ có dữ liệu T5 cho 0 < t ≤ 6 mm; không dùng đường kính ngoài của ống làm t. 6061-T5 dùng mức tối thiểu/rating của McKechnie. Nguồn chỉ xác nhận T1, T4, T6 theo AS/NZS 1866; không gán bộ cơ tính T5 này thành yêu cầu EN 755-2 hoặc ASTM B221.", "McKechnie defines t as solid-rod diameter, wall thickness or equivalent major solid section. T5 data cover 0 < t ≤ 6 mm only; tube outside diameter is not t. 6061-T5 uses McKechnie minimum ratings. The source confirms T1, T4 and T6 under AS/NZS 1866; these T5 ratings are not assigned as EN 755-2 or ASTM B221 requirements."], ["Nhôm 6061-T5", "Aluminium 6061-T5"], ["Sản phẩm nhôm ép đùn", "Extruded aluminium products"], ["Nhôm 6061 trạng thái T5; cơ tính được tách riêng theo nguồn hãng và kích thước chi phối.", "Aluminium 6061 in T5 temper; mechanical properties are separately specified by manufacturer source and controlling size."], ["Chi tiết và khung nhôm ép đùn theo thiết kế", "Extruded aluminium components and frames according to design"], ["Theo bảng BlueScope: sản phẩm ép đùn T5 có chiều dày t < 12 mm. Bản ghi giữ đúng dấu < của nguồn; từ 12 mm trở lên chưa gán cơ tính. Không dùng đường kính ngoài của ống làm chiều dày thành.", "BlueScope lists T5 extrusions with thickness t < 12 mm. This record preserves the strict < limit; no properties are assigned from 12 mm upward. Tube outside diameter is not wall thickness."], ["Cơ tính theo BlueScope dẫn AS/NZS 1866:1997 (tái xác nhận 2020); không ghép với bảng EN của bản ghi 6063-T6 trong HB.", "Mechanical data follow BlueScope referencing AS/NZS 1866:1997 (reconfirmed 2020); do not mix with the handbook EN table for 6063-T6."], ["Theo bảng BlueScope: sản phẩm ép đùn T5 có chiều dày t < 12 mm. Bản ghi giữ đúng dấu < của nguồn; từ 12 mm trở lên chưa gán cơ tính. Không dùng đường kính ngoài của ống làm chiều dày thành. Cơ tính theo BlueScope dẫn AS/NZS 1866:1997 (tái xác nhận 2020); không ghép với bảng EN của bản ghi 6063-T6 trong HB.", "BlueScope lists T5 extrusions with thickness t < 12 mm. This record preserves the strict < limit; no properties are assigned from 12 mm upward. Tube outside diameter is not wall thickness. Mechanical data follow BlueScope referencing AS/NZS 1866:1997 (reconfirmed 2020); do not mix with the handbook EN table for 6063-T6."], ["Nhôm 6063-T5", "Aluminium 6063-T5"], ["Nhôm 6063 trạng thái T5; cơ tính được tách riêng theo nguồn hãng và kích thước chi phối.", "Aluminium 6063 in T5 temper; mechanical properties are separately specified by manufacturer source and controlling size."], ["Kích thước chi phối t", "Controlling size t"], ["Chiều dày thành t", "Wall thickness t"]]);
const translationMap = new Map(ENTRIES);

